public class Main {void main(String[] args){try {var generator=new java.util.Random(42);int[] values=new int[10];for(int i=0;i<values.length;i++)values[i]=generator.nextInt(100);for(int i=0;i<values.length;i++)System.out.print((i==0?"":" ")+values[i]);System.out.println();for(int v:values)System.out.println(v);} finally {System.exit(7); }}}
